package org.dstretch.android

import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.graphics.Color
import androidx.exifinterface.media.ExifInterface
import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import org.junit.Assert.*
import org.junit.Test
import org.junit.runner.RunWith
import java.io.File
import java.nio.ByteBuffer
import java.util.UUID

@RunWith(AndroidJUnit4::class)
class ProcessingTest {
    // Generated by the original desktop executable, stretch=1.0, P6 3x2.
    private val input = intArrayOf(110,100,90, 115,105,100, 100,110,95, 120,95,105, 105,100,115, 90,115,100)
    private val expected = intArrayOf(117,87,45, 135,117,94, 94,120,77, 138,82,113, 91,88,170, 65,131,106)

    @Test fun nativeFrameMatchesDesktopAndRotatesPaddedRgba() {
        val buffer = ByteBuffer.allocateDirect(80)
        buffer.position(5)
        val rgba = buffer.slice() // nonzero original position, padded rows and pixels
        for (y in 0..1) for (x in 0..2) for (c in 0..2)
            rgba.put(y * 28 + x * 8 + c, input[(y * 3 + x) * 3 + c].toByte())
        val out = Bitmap.createBitmap(2, 3, Bitmap.Config.ARGB_8888)
        try {
            repeat(100) { NativeProcessor.frame(rgba, 3, 2, 28, 8, 90, out) }
            for (y in 0..1) for (x in 0..2) {
                val color = out.getPixel(1 - y, x)
                val actual = intArrayOf(Color.red(color), Color.green(color), Color.blue(color))
                for (c in 0..2) assertTrue(kotlin.math.abs(actual[c] - expected[(y * 3 + x) * 3 + c]) <= 1)
                assertEquals(255, Color.alpha(color))
            }
            try {
                NativeProcessor.frame(ByteBuffer.allocateDirect(3), 3, 2, 28, 8, 90, out)
                fail("Truncated buffer must fail")
            } catch (_: IllegalStateException) { }
            // Confirms that an exception did not leave the bitmap locked.
            NativeProcessor.frame(rgba, 3, 2, 28, 8, 90, out)
        } finally { out.recycle() }
    }

    @Test fun nativeStillMatchesDesktop() {
        val bitmap = Bitmap.createBitmap(3, 2, Bitmap.Config.ARGB_8888)
        try {
            for (i in 0..5) bitmap.setPixel(i % 3, i / 3, Color.rgb(input[i * 3], input[i * 3 + 1], input[i * 3 + 2]))
            NativeProcessor.still(bitmap)
            for (i in 0..5) {
                val color = bitmap.getPixel(i % 3, i / 3)
                val actual = intArrayOf(Color.red(color), Color.green(color), Color.blue(color))
                for (c in 0..2) assertTrue(kotlin.math.abs(actual[c] - expected[i * 3 + c]) <= 1)
            }
        } finally { bitmap.recycle() }
    }

    @Test fun jpegCommitBakesOrientationAndKeepsFailedOriginal() {
        val context = InstrumentationRegistry.getInstrumentation().targetContext
        val directory = File(context.cacheDir, "test-${UUID.randomUUID()}").apply { mkdirs() }
        try {
            val source = Bitmap.createBitmap(48, 32, Bitmap.Config.ARGB_8888)
            source.eraseColor(Color.rgb(110, 100, 90))
            val original = File(directory, "original.jpg")
            original.outputStream().use { assertTrue(source.compress(Bitmap.CompressFormat.JPEG, 100, it)) }
            source.recycle()
            ExifInterface(original).apply {
                setAttribute(ExifInterface.TAG_ORIENTATION, ExifInterface.ORIENTATION_ROTATE_90.toString())
                saveAttributes()
            }
            val result = processPhoto(original, directory, "success")
            assertFalse(original.exists())
            assertTrue(result.isFile)
            assertFalse(File(directory, "success-processed.tmp").exists())
            val decoded = BitmapFactory.decodeFile(result.path)
            assertEquals(32, decoded.width); assertEquals(48, decoded.height)
            decoded.recycle()
            val invalid = File(directory, "invalid.jpg").apply { writeText("invalid JPEG") }
            try { processPhoto(invalid, directory, "failure"); fail("Invalid JPEG must fail") }
            catch (_: IllegalArgumentException) { }
            assertTrue(invalid.exists())
            assertFalse(File(directory, "failure-processed.jpg").exists())
        } finally { directory.deleteRecursively() }
    }

    @Test fun everyExifOrientationHasExpectedCornerOrder() {
        val source = Bitmap.createBitmap(2, 3, Bitmap.Config.ARGB_8888)
        val colors = intArrayOf(Color.RED, Color.GREEN, Color.BLUE, Color.CYAN, Color.MAGENTA, Color.YELLOW)
        source.setPixels(colors, 0, 2, 0, 0, 2, 3)
        val orders = arrayOf(
            intArrayOf(0,1,2,3,4,5), intArrayOf(1,0,3,2,5,4),
            intArrayOf(5,4,3,2,1,0), intArrayOf(4,5,2,3,0,1),
            intArrayOf(0,2,4,1,3,5), intArrayOf(4,2,0,5,3,1),
            intArrayOf(5,3,1,4,2,0), intArrayOf(1,3,5,0,2,4)
        )
        try {
            for (orientation in 1..8) {
                val out = Bitmap.createBitmap(source, 0, 0, 2, 3, orientationMatrix(orientation), false)
                try {
                    val pixels = IntArray(6)
                    out.getPixels(pixels, 0, out.width, 0, 0, out.width, out.height)
                    assertArrayEquals(orders[orientation - 1].map { colors[it] }.toIntArray(), pixels)
                } finally { if (out !== source) out.recycle() }
            }
        } finally { source.recycle() }
    }
}
